#include "exotic/cognition/adaptation.hpp"
#include <algorithm>
#include <cmath>
namespace exotic::cognition {
std::vector<AdaptationProposal> AdaptationCapability::propose(const std::vector<AdaptationEvidence>& evidence,AdaptationTarget target,const std::string&target_id)const{std::vector<AdaptationProposal> out;if(target_id.empty())return out;double weighted=0,weight=0;for(const auto&e:evidence){const double w=std::clamp(e.reliability,0.0,1.0)*std::clamp(e.relevance,0.0,1.0);weighted+=std::clamp(e.valence,-1.0,1.0)*w;weight+=w;}if(weight<.10)return out;const double signal=weighted/weight;AdaptationProposal p;p.id="adapt-"+target_id;p.target=target;p.target_id=target_id;p.suggested_delta=std::clamp(signal*.10,-.10,.10);p.confidence=std::clamp(weight/static_cast<double>(std::max<std::size_t>(1,evidence.size())),0.0,1.0);p.rationale="Evidence suggests a bounded update; this is a proposal and does not mutate the target.";out.push_back(p);return out;}
AdaptationChoice AdaptationCapability::consider(const AdaptationProposal&p)const{AdaptationChoice c;c.proposal=p;const double magnitude=std::abs(p.suggested_delta);if(p.confidence<.35){c.decision=AdaptationDecision::ObserveMore;c.rationale="Evidence confidence is too low; preserve the current state and gather more evidence.";}else if(magnitude<.01){c.decision=AdaptationDecision::Defer;c.rationale="The proposed change is too small to justify a state transition now.";}else if(magnitude>.08&&p.confidence<.75){c.decision=AdaptationDecision::Defer;c.rationale="The change is comparatively large; defer rather than forcing an unstable update.";}else{c.decision=AdaptationDecision::Adopt;c.rationale="The bounded evidence-supported proposal is suitable for voluntary adoption; applying it remains a separate operation.";}return c;}
} // namespace exotic::cognition
